// Demo: BAR Mapping with Attributes — write-combining vs uncacheable throughput
var bytes=1*4096;
var wc=bytes/3.2e9*1e3,uc=bytes/0.4e9*1e3;
console.log('technique: BAR Mapping with Attributes');console.log('transfer: '+(bytes/1048576).toFixed(1)+' MB');
console.log('write-combining: '+wc.toFixed(1)+' ms, uncacheable: '+uc.toFixed(1)+' ms');
console.log('WC wins '+(uc/wc).toFixed(1)+'x for streaming writes');

